// Format relative time
function formatRelativeTime(dateStr) {
    if (!dateStr) return 'Never';
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
}

function ExpirationBadge({ expiresAt }) {
    if (!expiresAt) return null;
    const now = new Date();
    const expires = new Date(expiresAt);
    const daysLeft = Math.ceil((expires - now) / 86400000);

    let color, bg, label;
    if (daysLeft <= 0) {
        color = '#f87171'; bg = 'rgba(248, 113, 113, 0.15)'; label = 'Expired';
    } else if (daysLeft <= 7) {
        color = '#f87171'; bg = 'rgba(248, 113, 113, 0.12)'; label = `${daysLeft}d left`;
    } else if (daysLeft <= 30) {
        color = '#fbbf24'; bg = 'rgba(251, 191, 36, 0.12)'; label = `${daysLeft}d left`;
    } else {
        color = '#4ade80'; bg = 'rgba(74, 222, 128, 0.12)'; label = `${daysLeft}d left`;
    }

    return (
        <span style={{
            fontSize: '10px', fontWeight: 600, color, background: bg,
            padding: '1px 6px', borderRadius: '4px', textTransform: 'uppercase',
            animation: daysLeft <= 0 ? 'pulse 2s infinite' : 'none'
        }}>
            {label}
        </span>
    );
}

export default function IntegrationCard({
    integration,
    typeConfig,
    selected = false,
    onSelect,
    onEdit,
    onDelete,
    onTest,
    onSetDefault,
    onRotate
}) {
    const [testing, setTesting] = useState(false);

    const {
        id,
        label,
        integration_type,
        key_preview,
        test_status,
        is_default,
        last_tested_at,
        last_used_at,
        created_at,
        expires_at,
        rotated_at,
        visibility,
        folder_id,
        use_count
    } = integration;

    const config = typeConfig || INTEGRATION_TYPES[integration_type] || {
        id: integration_type,
        name: integration_type,
        color: '#6B7280'
    };

    const Icon = integrationIcons[integration_type] || integrationIcons.custom;

    // VAULT-INTEG P8: test_depth (API-fetched types) / testDepth (generated
    // static fallback, src/config/integrationTypes.js) both carry the same
    // 3-way enum — a format-only type's "success" is a credential SHAPE
    // check, never a real network probe, and must never read the same as a
    // live "Connected". See services/auth/config/integrationTypeRegistry.js
    // getTestDepth().
    const isFormatOnly = (config.test_depth || config.testDepth) === 'format-only';

    const testStatusText = useMemo(() => {
        if (testing) return 'Testing...';
        if (!test_status || test_status === 'untested') return 'Not tested';
        if (test_status === 'success') return isFormatOnly ? 'Format checked' : 'Connected';
        return 'Connection failed';
    }, [test_status, testing, isFormatOnly]);

    const testStatusTitle = useMemo(() => {
        if (test_status === 'success' && isFormatOnly) {
            return 'Format check only — no live connection was made to the provider';
        }
        return testStatusText;
    }, [test_status, isFormatOnly, testStatusText]);

    // Handle test with loading state
    const handleTest = useCallback(async () => {
        setTesting(true);
        try {
            await onTest();
        } finally {
            setTesting(false);
        }
    }, [onTest]);

    return (
        <div className={`integration-card ${is_default ? 'integration-card--default' : ''} ${selected ? 'integration-card--selected' : ''}`}>
            {/* Selection Checkbox */}
            {onSelect && (
                <label className="integration-card__checkbox" onClick={(e) => e.stopPropagation()}>
                    <input
                        type="checkbox"
                        checked={selected}
                        onChange={(e) => onSelect(e.target.checked)}
                    />
                    <span className="integration-card__checkbox-mark" />
                </label>
            )}

            <div className="integration-card__header">
                <div
                    className="integration-card__icon"
                    style={{ backgroundColor: `${config.color}20`, color: config.color }}
                >
                    {Icon}
                </div>
                <div className="integration-card__info">
                    <h4 className="integration-card__label">
                        {label}
                    </h4>
                    <p className="integration-card__type">{config.name}</p>
                    <div className="integration-card__badges">
                        {is_default && (
                            <span className="integration-card__badge integration-card__badge--default">
                                Default
                            </span>
                        )}
                        {visibility && visibility !== 'org' && (
                            <span className={`integration-card__badge integration-card__badge--${visibility}`}>
                                {visibility === 'personal' ? 'Personal' : 'Team'}
                            </span>
                        )}
                        {folder_id && (
                            <span className="integration-card__badge integration-card__badge--folder">
                                <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                    <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z" />
                                </svg>
                            </span>
                        )}
                        <ExpirationBadge expiresAt={expires_at} />
                    </div>
                </div>

                {/* Health Indicator */}
                <div
                    className={`integration-card__health integration-card__health--${test_status || 'untested'} ${test_status === 'success' && isFormatOnly ? 'integration-card__health--format-only' : ''}`}
                    title={testStatusTitle}
                />
            </div>

            <div className="integration-card__key">
                <KeyIcon />
                <span>{key_preview || '****'}</span>
            </div>

            <div className="integration-card__meta">
                <span className="integration-card__test-status" title={testStatusTitle}>
                    <span className={`integration-card__test-dot integration-card__test-dot--${test_status || 'untested'} ${test_status === 'success' && isFormatOnly ? 'integration-card__test-dot--format-only' : ''}`} />
                    {testStatusText}
                    {test_status === 'success' && isFormatOnly && (
                        <span
                            className="integration-card__badge integration-card__badge--format-only"
                            title="Format check only, no live connection made"
                        >
                            format check only
                        </span>
                    )}
                </span>
                <span className="integration-card__usage">
                    {use_count != null ? `${use_count} uses` : `Used: ${formatRelativeTime(last_used_at)}`}
                </span>
            </div>

            <div className="integration-card__actions">
                <button
                    className={`integration-card__action ${testing ? 'integration-card__action--testing' : ''}`}
                    onClick={handleTest}
                    disabled={testing}
                    title="Test connection"
                >
                    {testing ? <><SpinnerIcon /> Testing...</> : <><TestIcon /> Test</>}
                </button>
                {onRotate && (
                    <button
                        className="integration-card__action"
                        onClick={onRotate}
                        title="Rotate credentials"
                    >
                        <RotateIcon /> Rotate
                    </button>
                )}
                <button
                    className="integration-card__action"
                    onClick={onEdit}
                    title="Edit"
                >
                    <EditIcon /> Edit
                </button>
                {!is_default && (
                    <button
                        className="integration-card__action"
                        onClick={onSetDefault}
                        title="Set as default"
                    >
                        <StarIcon />
                    </button>
                )}
                <button
                    className="integration-card__action integration-card__action--danger"
                    onClick={onDelete}
                    title="Delete"
                >
                    <TrashIcon />
                </button>
            </div>
        </div>
    );
}
